draw:
var V = 6.0, Rg = p.rg;
var R1 = p.r1, R2 = p.r2, R3 = p.r3, R4 = p.r4;

// node equations for VA, VB with P at 6 V and Q at 0 V
var a11 = 1/R1 + 1/R2 + 1/Rg, a12 = -1/Rg, b1 = V/R1;
var a22 = 1/R3 + 1/R4 + 1/Rg, a21 = -1/Rg, b2 = V/R3;
var det = a11*a22 - a12*a21;
var VA = (b1*a22 - a12*b2) / det;
var VB = (a11*b2 - b1*a21) / det;
var Ig = (VA - VB) / Rg;
var Itot = (V - VA)/R1 + (V - VB)/R3;
var Rpq = V / Itot;

var cx = W/2, cy = H/2;
var rx = Math.min(W*0.34, 190), ry = Math.min(H*0.30, 78);
var P = [cx - rx, cy], Q = [cx + rx, cy];
var A = [cx, cy - ry], B = [cx, cy + ry];

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.textAlign = "center";
ctx.textBaseline = "middle";

function wire(u, v, col) {
  ctx.strokeStyle = col;
  ctx.beginPath(); ctx.moveTo(u[0], u[1]); ctx.lineTo(v[0], v[1]); ctx.stroke();
}
function box(u, v, label, col) {
  var mx = (u[0]+v[0])/2, my = (u[1]+v[1])/2;
  var dx = v[0]-u[0], dy = v[1]-u[1];
  var L = Math.sqrt(dx*dx + dy*dy); dx /= L; dy /= L;
  var w = 20, h = 9;
  ctx.save();
  ctx.translate(mx, my);
  ctx.rotate(Math.atan2(dy, dx));
  ctx.fillStyle = C.paper;
  ctx.fillRect(-w, -h, 2*w, 2*h);
  ctx.strokeStyle = col;
  ctx.strokeRect(-w, -h, 2*w, 2*h);
  ctx.restore();
  ctx.fillStyle = C.ink;
  ctx.fillText(label, mx - dy*22, my + dx*22);
}
function node(u, name, volts) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(u[0], u[1], 4, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.fillText(name + "  " + volts, u[0], u[1] - 16);
}

wire(P, A, C.rule); wire(A, Q, C.rule);
wire(P, B, C.rule); wire(B, Q, C.rule);
wire(A, B, C.figure);

box(P, A, R1.toFixed(0) + " Ω", C.rule);
box(A, Q, R2.toFixed(0) + " Ω", C.rule);
box(P, B, R3.toFixed(0) + " Ω", C.rule);
box(B, Q, R4.toFixed(0) + " Ω", C.rule);
box(A, B, Rg.toFixed(0) + " Ω", C.figure);

ctx.fillStyle = C.ink;
ctx.fillText("P  6.00 V", P[0] - 4, P[1] - 16);
ctx.fillText("Q  0.00 V", Q[0] + 4, Q[1] - 16);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(P[0], P[1], 4, 0, Math.PI*2); ctx.fill();
ctx.beginPath(); ctx.arc(Q[0], Q[1], 4, 0, Math.PI*2); ctx.fill();
node(A, "A", VA.toFixed(3) + " V");
ctx.fillStyle = C.ink;
ctx.fillText("B  " + VB.toFixed(3) + " V", B[0], B[1] + 18);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(B[0], B[1], 4, 0, Math.PI*2); ctx.fill();

// animated charge in the bridge arm, speed set by the galvanometer current
var speed = Math.min(1.2, Math.abs(Ig) * 260);
var dir = Ig >= 0 ? 1 : -1;
if (speed > 0.004) {
  for (var k = 0; k < 4; k++) {
    var f = ((t * speed + k/4) % 1);
    var yy = A[1] + dir * f * (B[1] - A[1]);
    if (dir < 0) yy = B[1] + f * (A[1] - B[1]);
    ctx.fillStyle = C.figure;
    ctx.beginPath(); ctx.arc(A[0], yy, 3, 0, Math.PI*2); ctx.fill();
  }
} else {
  ctx.fillStyle = C.figure;
  ctx.fillText("balanced: no current", A[0] + 96, cy);
}

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("ratio PA/AQ = " + (R1/R2).toFixed(3), 8, H - 26);
ctx.fillText("ratio PB/BQ = " + (R3/R4).toFixed(3), 8, H - 10);

out.note = "V(A) - V(B) = " + (VA - VB).toFixed(4) + " V, bridge current = "
  + (Ig*1000).toFixed(3) + " mA, R(P to Q) = " + Rpq.toFixed(2) + " Ω";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
ctx.textBaseline = "middle";

var s = Math.min((W - 150) / 1.45, (H - 60) / 1.35);
var ox = 46, oy = H - 26;
function X(v) { return ox + (v[0] + 0.45 * v[2]) * s; }
function Y(v) { return oy - (v[1] + 0.35 * v[2]) * s; }

var V = [];
for (var x = 0; x < 2; x++) for (var y = 0; y < 2; y++) for (var z = 0; z < 2; z++) V.push([x,y,z]);
function key(v) { return v[0] + "" + v[1] + "" + v[2]; }

var A = [0,0,0], G = [1,1,1];
function dist(u, v) { return Math.abs(u[0]-v[0]) + Math.abs(u[1]-v[1]) + Math.abs(u[2]-v[2]); }

// edges
for (var i = 0; i < V.length; i++) for (var j = i+1; j < V.length; j++) {
  if (dist(V[i], V[j]) !== 1) continue;
  var dA = Math.min(dist(V[i], A), dist(V[j], A));
  var dB = Math.min(dist(V[i], G), dist(V[j], G));
  var near = (dA === 0) || (dB === 0);
  ctx.strokeStyle = near ? C.accent : C.rule;
  ctx.lineWidth = near ? 2 : 1.4;
  ctx.beginPath(); ctx.moveTo(X(V[i]), Y(V[i])); ctx.lineTo(X(V[j]), Y(V[j])); ctx.stroke();
}

// vertices, coloured by distance from A
for (var i2 = 0; i2 < V.length; i2++) {
  var v = V[i2], d = dist(v, A);
  ctx.fillStyle = (d === 0 || d === 3) ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(X(v), Y(v), (d === 0 || d === 3) ? 6 : 5, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = C.ink;
  var lab = d === 0 ? "A" : (d === 3 ? "G" : (d === 1 ? "1" : "2"));
  ctx.fillText(lab, X(v) + 12, Y(v) - 11);
}

ctx.lineWidth = 1;
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
var tx = W - 132;
ctx.fillText("A to tier 1:  R/3", tx, 24);
ctx.fillText("tier 1 to 2:  R/6", tx, 44);
ctx.fillText("tier 2 to G:  R/3", tx, 64);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(tx, 76); ctx.lineTo(tx + 116, 76); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("total  =  5R/6", tx, 92);
ctx.fillStyle = C.faint;
ctx.fillText("the three 1s share a potential,", tx, 118);
ctx.fillText("and so do the three 2s", tx, 134);

out.note = "Every corner marked 1 is one step from A; every corner marked 2 is two steps. Corners with the same label sit at the same potential.";

var Rs = p.rs, Rp = p.rp, n = Math.round(p.n);

// exact infinite-ladder value: X is the resistance looking in at a shunt node
var Xinf = (-Rp + Math.sqrt(Rp*Rp + 4*Rp*Rs)) / 2;
var Rinf = Rs + Xinf;

// finite ladder with n sections, built from the far end backwards
var X = Rp;
for (var k = 1; k < n; k++) { X = 1 / (1/Rp + 1/(Rs + X)); }
var Rfin = Rs + X;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.textAlign = "center";
ctx.textBaseline = "middle";

var top = H * 0.30, bot = H * 0.78;
var left = 34, right = W - 26;
var seg = (right - left) / (n + 0.6);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(left, bot); ctx.lineTo(right, bot); ctx.stroke();

function box(x1, y1, x2, y2, label) {
  var mx = (x1+x2)/2, my = (y1+y2)/2;
  var horiz = Math.abs(x2-x1) > Math.abs(y2-y1);
  var w = horiz ? 15 : 8, h = horiz ? 7 : 14;
  ctx.fillStyle = C.paper;
  ctx.fillRect(mx-w, my-h, 2*w, 2*h);
  ctx.strokeStyle = C.rule;
  ctx.strokeRect(mx-w, my-h, 2*w, 2*h);
  ctx.fillStyle = C.ink;
  if (horiz) ctx.fillText(label, mx, my - 16); else ctx.fillText(label, mx + 26, my);
}

var Iin = 1.0;
var Icar = Iin;
for (var i = 0; i < n; i++) {
  var x0 = left + i * seg, x1 = left + (i + 1) * seg;
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(x0, top); ctx.lineTo(x1, top); ctx.stroke();
  box(x0, top, x1, top, Rs.toFixed(1));
  ctx.beginPath(); ctx.moveTo(x1, top); ctx.lineTo(x1, bot); ctx.stroke();
  box(x1, top, x1, bot, Rp.toFixed(1));

  // rest of the ladder beyond this node
  var Xhere = Rp;
  for (var k2 = 1; k2 < n - i; k2++) { Xhere = 1 / (1/Rp + 1/(Rs + Xhere)); }
  var beyond = (i === n - 1) ? Infinity : (Rs + (function () {
    var Z = Rp;
    for (var m = 1; m < n - i - 1; m++) { Z = 1 / (1/Rp + 1/(Rs + Z)); }
    return Z;
  })());
  var fshunt = (beyond === Infinity) ? 1 : beyond / (Rp + beyond);
  var Ishunt = Icar * fshunt;

  ctx.fillStyle = C.figure;
  ctx.fillText(Ishunt.toFixed(3), x1 + 26, (top + bot) / 2 + 20);

  // animated charge sliding along this rung
  var ph = (t * 0.55 + i * 0.17) % 1;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x0 + ph * seg, top, 3, 0, Math.PI*2); ctx.fill();

  Icar = Icar - Ishunt;
}

ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("1.000 A in", left - 26, top - 26);
ctx.fillStyle = C.figure;
ctx.fillText("shunt currents, in amps, below each rung", left, H - 8);

out.note = n + " section" + (n === 1 ? "" : "s") + ": R = " + Rfin.toFixed(4)
  + " Ω    infinite ladder: R = " + Rinf.toFixed(4) + " Ω";
